-- LOCO owner-authorized two independent menus and 6 stamps / 10% reward
BEGIN;SET LOCAL lock_timeout='5s';
CREATE TEMP TABLE loco_before AS SELECT jsonb_build_object('products',(SELECT md5(jsonb_agg(to_jsonb(t) ORDER BY id)::text) FROM menu_products t WHERE cafe_id<>'321fd305-1883-48df-ab69-829cf7d1bc48'),'categories',(SELECT md5(jsonb_agg(to_jsonb(t) ORDER BY id)::text) FROM menu_categories t WHERE cafe_id<>'321fd305-1883-48df-ab69-829cf7d1bc48'),'branches',(SELECT md5(jsonb_agg(to_jsonb(t) ORDER BY id)::text) FROM branches t WHERE cafe_id<>'321fd305-1883-48df-ab69-829cf7d1bc48'),'offers',(SELECT md5(jsonb_agg(to_jsonb(t) ORDER BY id)::text) FROM offers t WHERE cafe_id<>'321fd305-1883-48df-ab69-829cf7d1bc48'),'programs',(SELECT md5(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text) FROM cafe_loyalty_programs t WHERE cafe_id<>'321fd305-1883-48df-ab69-829cf7d1bc48'),'identity',(SELECT md5(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text) FROM cafe_custom_identity t WHERE cafe_id<>'321fd305-1883-48df-ab69-829cf7d1bc48'),'settings',(SELECT md5(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text) FROM cafe_settings t WHERE cafe_id<>'321fd305-1883-48df-ab69-829cf7d1bc48')) snapshot;
DO $guard$ BEGIN
IF NOT EXISTS(SELECT 1 FROM cafes WHERE id='321fd305-1883-48df-ab69-829cf7d1bc48' AND slug='brand-9a8c97305195' AND status='active' AND deleted_at IS NULL) THEN RAISE EXCEPTION 'LOCO identity changed'; END IF;
IF EXISTS(SELECT 1 FROM menu_products WHERE cafe_id='321fd305-1883-48df-ab69-829cf7d1bc48') OR EXISTS(SELECT 1 FROM menu_categories WHERE cafe_id='321fd305-1883-48df-ab69-829cf7d1bc48') OR EXISTS(SELECT 1 FROM branches WHERE cafe_id='321fd305-1883-48df-ab69-829cf7d1bc48') OR EXISTS(SELECT 1 FROM offers WHERE cafe_id='321fd305-1883-48df-ab69-829cf7d1bc48') OR EXISTS(SELECT 1 FROM cafe_loyalty_programs WHERE cafe_id='321fd305-1883-48df-ab69-829cf7d1bc48') THEN RAISE EXCEPTION 'LOCO already configured; inspect before changing data';END IF;
END $guard$;
UPDATE cafe_settings SET logo_storage_path='321fd305-1883-48df-ab69-829cf7d1bc48/loco-20261101/logo-48754a23ba5e.png',logo_url=null,description='قهوة وحلا ومزاج لوكو',updated_at=now() WHERE cafe_id='321fd305-1883-48df-ab69-829cf7d1bc48';
DO $verify$ DECLARE actual jsonb; BEGIN SELECT jsonb_build_object('products',(SELECT md5(jsonb_agg(to_jsonb(t) ORDER BY id)::text) FROM menu_products t WHERE cafe_id<>'321fd305-1883-48df-ab69-829cf7d1bc48'),'categories',(SELECT md5(jsonb_agg(to_jsonb(t) ORDER BY id)::text) FROM menu_categories t WHERE cafe_id<>'321fd305-1883-48df-ab69-829cf7d1bc48'),'branches',(SELECT md5(jsonb_agg(to_jsonb(t) ORDER BY id)::text) FROM branches t WHERE cafe_id<>'321fd305-1883-48df-ab69-829cf7d1bc48'),'offers',(SELECT md5(jsonb_agg(to_jsonb(t) ORDER BY id)::text) FROM offers t WHERE cafe_id<>'321fd305-1883-48df-ab69-829cf7d1bc48'),'programs',(SELECT md5(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text) FROM cafe_loyalty_programs t WHERE cafe_id<>'321fd305-1883-48df-ab69-829cf7d1bc48'),'identity',(SELECT md5(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text) FROM cafe_custom_identity t WHERE cafe_id<>'321fd305-1883-48df-ab69-829cf7d1bc48'),'settings',(SELECT md5(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text) FROM cafe_settings t WHERE cafe_id<>'321fd305-1883-48df-ab69-829cf7d1bc48')) INTO actual; IF actual IS DISTINCT FROM (SELECT snapshot FROM loco_before) THEN RAISE EXCEPTION 'Another brand changed';END IF;IF (SELECT count(*) FROM menu_products WHERE cafe_id='321fd305-1883-48df-ab69-829cf7d1bc48')<>72 THEN RAISE EXCEPTION 'Catalog count mismatch';END IF;END $verify$;
COMMIT;
